insert into publishers (name) values ('Fireworks AI') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Fireworks AI', 'fireworks-ai', p.id, 'Production inference platform for open and custom models.', 'Fireworks offers low-latency inference APIs and deployment tooling for generative models.', 'https://fireworks.ai', 'published', 'Paid', 'Usage-based', true, false, false, ARRAY['inference', 'serverless', 'api']::text[], ARRAY['Production inference focus']::text[], ARRAY['Paid platform']::text[], ARRAY['Developers', 'Enterprises']::text[], current_date from publishers p where p.name = 'Fireworks AI' on conflict (slug) do nothing;
